CREATE TABLE IF NOT EXISTS transaction_documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID NOT NULL REFERENCES property_transactions(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('OFFER_ACCEPTANCE','IDENTITY','FINANCE','COMPLIANCE','TRANSFER','OTHER')),label TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('REQUIRED','SUBMITTED','VERIFIED','REJECTED')),storage_key TEXT,notes TEXT,submitted_by UUID REFERENCES users(id) ON DELETE SET NULL,verified_by UUID REFERENCES users(id) ON DELETE SET NULL,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS transaction_documents_kind_idx ON transaction_documents(transaction_id,kind);
CREATE INDEX IF NOT EXISTS transaction_documents_transaction_idx ON transaction_documents(transaction_id);
CREATE TABLE IF NOT EXISTS transaction_audit_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID NOT NULL REFERENCES property_transactions(id) ON DELETE CASCADE,actor_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS transaction_audit_events_transaction_idx ON transaction_audit_events(transaction_id,created_at);